\"\"\"Minimal OpenAI Responses API client using only the standard library.\"\"\"

import json
import os
import urllib.error
import urllib.request

DEFAULT_BASE_URL = \"https://api.openai.com/v1\"
DEFAULT_MODEL = \"gpt-4o-mini\"


class OpenAIError(Exception):
    \"\"\"Raised when the API request fails.\"\"\"

    def __init__(self, message, status=None, body=None):
        super().__init__(message)
        self.status = status
        self.body = body


class OpenAIClient:
    def __init__(self, api_key=None, model=DEFAULT_MODEL, base_url=None, timeout=60):
        self.api_key = api_key or os.environ.get(\"OPENAI_API_KEY\")
        if not self.api_key:
            raise ValueError(\"API key required: pass api_key or set OPENAI_API_KEY\")
        self.model = model
        self.base_url = (base_url or os.environ.get(\"OPENAI_BASE_URL\") or DEFAULT_BASE_URL).rstrip(\"/\")
        self.timeout = timeout

    def create_response(self, prompt, model=None, instructions=None, store=False, **extra):
        \"\"\"Send a text prompt and return the full response dict.

        "'`store=False` by default so the prompt is not retained for later
        retrieval on OpenAI'"'s side. Extra keyword args are passed through
        in the request body (e.g. temperature, max_output_tokens).
        \"\"\"
        payload = {\"model\": model or self.model, \"input\": prompt, \"store\": store}
        if instructions:
            payload[\"instructions\"] = instructions
        payload.update(extra)

        request = urllib.request.Request(
            f\"{self.base_url}/responses\",
            data=json.dumps(payload).encode(\"utf-8\"),
            headers={
                \"Authorization\": f\"Bearer {self.api_key}\",
                \"Content-Type\": \"application/json\",
            },
            method=\"POST\",
        )
        try:
            with urllib.request.urlopen(request, timeout=self.timeout) as response:
                return json.loads(response.read().decode(\"utf-8\"))
        except urllib.error.HTTPError as error:
            body = error.read().decode(\"utf-8\", errors=\"replace\")
            raise OpenAIError(f\"HTTP {error.code}: {body}\", status=error.code, body=body) from None
        except urllib.error.URLError as error:
            raise OpenAIError(f\"Connection error: {error.reason}\") from None

    @staticmethod
    def extract_text(response):
        \"\"\"Concatenate the output text from a response dict.\"\"\"
        if isinstance(response.get(\"output_text\"), str):
            return response[\"output_text\"]
        parts = []
        for item in response.get(\"output\", []):
            if item.get(\"type\") == \"message\":
                for content in item.get(\"content\", []):
                    if content.get(\"type\") == \"output_text\":
                        parts.append(content.get(\"text\", \"\"))
        return \"\".join(parts)

    def ask(self, prompt, **kwargs):
        \"\"\"Send a prompt and return only the reply text.\"\"\"
        return self.extract_text(self.create_response(prompt, **kwargs))


def ask(prompt, **kwargs):
    \"\"\"Convenience wrapper: one-shot prompt using environment configuration.\"\"\"
    return OpenAIClient().ask(prompt, **kwargs)


if __name__ == \"__main__\":
    import sys

    text = \" \".join(sys.argv[1:]) or sys.stdin.read()
    print(ask(text))
EOF
